function calcularDescuento(cliente: Cliente, total: number): number {
  if (!cliente.esActivo) return 0;
  if (total < MONTO_MINIMO_DESCUENTO) return 0;
  return cliente.esVip ? total * 0.15 : total * 0.05;
}

